"""matplotlib._tight_layout — tight layout computation.

The plotly backend handles axis sizing autonomously, so the layout
solver here just translates the requested ``pad``/``h_pad``/``w_pad``
into figure-fraction subplot-params and calls ``fig.subplots_adjust``.
That's what upstream's auto_adjust_subplotpars eventually does too,
just via a more elaborate constraint solve.
"""


def auto_adjust_subplotpars(fig, renderer=None, nrows_ncols=(1, 1),
                              num1num2_list=None, subplot_list=None,
                              ax_bbox_list=None, pad=1.08,
                              h_pad=None, w_pad=None, rect=None):
    """Compute new subplot-params that leave ``pad`` font units of
    padding around the figure edges and ``h_pad``/``w_pad`` between
    subplots. Returns a dict matching upstream's signature."""
    if fig is None:
        return {}
    # Translate pad (in font units, default 1.08) to a figure fraction
    # based on the figure's height. Tight-layout normally measures the
    # actual rendered text/title sizes; the shim approximates by
    # treating a font unit as ~12pt at the figure's dpi.
    size = fig.get_size_inches() if hasattr(fig, 'get_size_inches') else (8, 6)
    dpi = fig.get_dpi() if hasattr(fig, 'get_dpi') else 100.0
    font_inches = 12.0 / 72.0       # 12pt → inches
    pad_w = pad * font_inches / max(size[0], 1e-9)
    pad_h = pad * font_inches / max(size[1], 1e-9)
    if rect is None:
        rect = (0, 0, 1, 1)
    left = rect[0] + pad_w
    bottom = rect[1] + pad_h
    right = rect[0] + rect[2] - pad_w
    top = rect[1] + rect[3] - pad_h
    out = dict(left=left, bottom=bottom, right=right, top=top)
    if w_pad is not None:
        out['wspace'] = w_pad * font_inches / max(size[0], 1e-9)
    if h_pad is not None:
        out['hspace'] = h_pad * font_inches / max(size[1], 1e-9)
    return out


def get_tight_layout_figure(fig, axes_list, subplotspec_list, renderer,
                              pad=1.08, h_pad=None, w_pad=None, rect=None):
    """Top-level tight-layout entry point: builds new SubplotParams and
    returns them as a dict suitable for ``fig.subplots_adjust(**out)``."""
    return auto_adjust_subplotpars(
        fig, renderer,
        nrows_ncols=(1, 1),
        subplot_list=axes_list,
        pad=pad, h_pad=h_pad, w_pad=w_pad, rect=rect)


def get_subplotspec_list(axes_list, grid_spec=None):
    """Return a list of SubplotSpec objects, one per axes — or ``None``
    for axes that don't belong to a gridspec. Mirrors upstream's helper."""
    out = []
    for ax in axes_list:
        spec = getattr(ax, 'get_subplotspec', None)
        out.append(spec() if callable(spec) else None)
    return out
